def f(gi):
    g=np.array(gi); n=len(gi)
    c0=int(np.where(np.array(gi)==2)[0][0])
    N=n
    out=[[0]*N for _ in range(N)]
    for r in range(n):
        for cc in (c0-r,c0+r):
            if 0<=cc<n: out[r][cc]=2
    k=1
    while True:
        ar,ac=2*k,c0-2*k
        if ar>=N: break
        for rr in range(ar,N):
            cc1=ac+(rr-ar); cc2=ac-(rr-ar)
            for cc in (cc1,cc2):
                if 0<=cc<N and out[rr][cc]==0:
                    out[rr][cc]=1
        k+=1
    return out
